macro_rules! deps {
    () => {
        MetaTemplate!();
        ParseError!();
        Mode!();
        Op!();
    };
}

macro_rules! next_op {
    () => {
        deps!();
        fn next_op (edition : impl Copy + Fn (SyntaxContext) -> Edition , first_peeked : TtElement < '_ , Span > , src : & mut TtIter < '_ , Span > , mode : Mode ,) -> Result < Op , ParseError > { let res = match first_peeked { TtElement :: Leaf (tt :: Leaf :: Punct (p @ tt :: Punct { char : '$' , .. })) => { src . next () . expect ("first token already peeked") ; let second = match src . next () { None => { return Ok (Op :: Punct ({ let mut res = ArrayVec :: new () ; res . push (* p) ; Box :: new (res) })) ; } Some (it) => it , } ; match second { TtElement :: Subtree (subtree , mut subtree_iter) => match subtree . delimiter . kind { tt :: DelimiterKind :: Parenthesis => { let (separator , kind) = parse_repeat (src) ? ; let tokens = MetaTemplate :: parse (edition , subtree_iter , mode) ? ; Op :: Repeat { tokens , separator : separator . map (Arc :: new) , kind } } tt :: DelimiterKind :: Brace => match mode { Mode :: Template => parse_metavar_expr (& mut subtree_iter) . map_err (| () | { ParseError :: unexpected ("invalid metavariable expression") }) ? , Mode :: Pattern => { return Err (ParseError :: unexpected ("`${}` metavariable expressions are not allowed in matchers" ,)) ; } } , _ => { return Err (ParseError :: expected ("expected `$()` repetition or `${}` expression" ,)) ; } } , TtElement :: Leaf (leaf) => match leaf { tt :: Leaf :: Ident (ident) if ident . sym == sym :: crate_ => { Op :: Ident (tt :: Ident { sym : sym :: dollar_crate , span : ident . span , is_raw : tt :: IdentIsRaw :: No , }) } tt :: Leaf :: Ident (ident) => { let kind = eat_fragment_kind (edition , src , mode) ? ; let name = ident . sym . clone () ; let id = ident . span ; Op :: Var { name , kind , id } } tt :: Leaf :: Literal (lit) if is_boolean_literal (lit) => { let kind = eat_fragment_kind (edition , src , mode) ? ; let name = lit . symbol . clone () ; let id = lit . span ; Op :: Var { name , kind , id } } tt :: Leaf :: Punct (punct @ tt :: Punct { char : '$' , .. }) => match mode { Mode :: Pattern => { return Err (ParseError :: unexpected ("`$$` is not allowed on the pattern side" ,)) ; } Mode :: Template => Op :: Punct ({ let mut res = ArrayVec :: new () ; res . push (* punct) ; Box :: new (res) }) , } , tt :: Leaf :: Punct (_) | tt :: Leaf :: Literal (_) => { return Err (ParseError :: expected ("expected ident")) ; } } , } } TtElement :: Leaf (tt :: Leaf :: Literal (it)) => { src . next () . expect ("first token already peeked") ; Op :: Literal (it . clone ()) } TtElement :: Leaf (tt :: Leaf :: Ident (it)) => { src . next () . expect ("first token already peeked") ; Op :: Ident (it . clone ()) } TtElement :: Leaf (tt :: Leaf :: Punct (_)) => { let puncts = src . expect_glued_punct () . unwrap () ; Op :: Punct (Box :: new (puncts)) } TtElement :: Subtree (subtree , subtree_iter) => { src . next () . expect ("first token already peeked") ; let tokens = MetaTemplate :: parse (edition , subtree_iter , mode) ? ; Op :: Subtree { tokens , delimiter : subtree . delimiter } } } ; Ok (res) }
    };
}

next_op!();